entries[24131] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerschießt einen Stachel, der das Ziel 12 Sek. lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich im Verlauf von 6 Sek. insgesamt 300 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
entries[24132] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "155 Mana 8 - 35 Meter Reichweite\nSofort 2 min Abklingzeit\nBenötigt Distanzwaffe\nVerschießt einen Stachel, der das Ziel 12 Sek. lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich 12 Sek. lang 420 Naturschaden. Kann nicht im Kampf verwendet werden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
